150: 		if request.Outcome == "verdict" {
151: 			headSet[fmt.Sprintf("%d/%s/%s/%s", request.TaskID, request.Repository, request.RequestedHead, request.Provider)] = true
152: 			row.Verdicts++
153: 			latencies = append(latencies, request.SettledAt-request.RequestedAt)
154: 			var outcome string
155: 			if err := db.QueryRowContext(ctx, `SELECT verdict FROM verdicts WHERE id=?`, request.VerdictID).Scan(&outcome); err != nil {
156: 				return row, nil, err
157: 			}
158: 			if outcome == "inconclusive" {
159: 				row.Inconclusive++
160: 				row.InconclusiveShare++
161: 			}
162: 		}
163: 	}
164: 	row.ReviewedHeads = len(headSet)
165: 	if row.Requests > 0 {
166: 		row.Reliability = float64(row.Verdicts) / float64(row.Requests)
167: 	}
168: 	if row.Verdicts > 0 {
169: 		row.InconclusiveShare /= float64(row.Verdicts)
170: 	}
171: 	if len(latencies) > 0 {
172: 		median := medianInt64(latencies)
173: 		row.MedianLatencyMS = &median
174: 	}
175: 	if row.Requests > 0 {
176: 		pass := row.Reliability >= 0.95
177: 		row.ReliabilityPass = &pass
178: 	}
179: 	if row.Requests > 0 {
180: 		row.WrongHeadRate = float64(row.WrongHead) / float64(row.Requests)
181: 	}
182: 	wrongPass := row.WrongHead == 0
183: 	row.WrongHeadPass = &wrongPass
184: 	if row.Verdicts > 0 {
185: 		pass := row.InconclusiveShare <= 0.10
186: 		row.InconclusivePass = &pass
187: 	}
188: 	builtinLatency, err := builtinReviewLatency(ctx, db, project.ID)
189: 	if err != nil {
190: 		return row, nil, err
191: 	}
192: 	if builtinLatency != nil {
193: 		row.BuiltinMedianLatencyMS = builtinLatency
194: 		limit := *builtinLatency * 3 / 2
195: 		row.LatencyLimitMS = &limit
196: 		if row.MedianLatencyMS != nil {
197: 			pass := *row.MedianLatencyMS <= limit
198: 			row.LatencyPass = &pass
199: 		}
200: 	}
201: 	findings, err := builtinFixedFindings(ctx, db, project.ID)
202: 	if err != nil {
203: 		return row, nil, err
204: 	}
205: 	greenhouse, err := db.QueryContext(ctx, `SELECT r.task_id,r.repo,r.requested_head,v.findings_path FROM greenhouse_review_requests r JOIN verdicts v ON v.id=r.verdict_id WHERE r.project_id=? AND r.outcome='verdict'`, project.ID)
206: 	if err != nil {
207: 		return row, nil, err
208: 	}
209: 	for greenhouse.Next() {
210: 		var taskID int64
211: 		var repo, head, findingsPath string
212: 		if err := greenhouse.Scan(&taskID, &repo, &head, &findingsPath); err != nil {
213: 			greenhouse.Close()
214: 			return row, nil, err
215: 		}
216: 		data, err := os.ReadFile(findingsPath)
217: 		if err != nil {
218: 			greenhouse.Close()
219: 			return row, nil, err
220: 		}
221: 		var ghFindings []comparisonFinding
222: 		if err := json.Unmarshal(data, &ghFindings); err != nil {
223: 			greenhouse.Close()
224: 			return row, nil, err
225: 		}
226: 		matchedParallel := make([]bool, len(ghFindings))
227: 		for _, builtin := range findings {
228: 			if builtin.TaskID != taskID || builtin.Head != head || builtin.Repo != repo {
229: 				continue
230: 			}
231: 			row.RecallPairs++
232: 			matched := false
233: 			for i, parallel := range ghFindings {
234: 				if !matchedParallel[i] && parallel.File == builtin.Path && strings.Contains(strings.ToLower(parallel.Explanation), strings.ToLower(builtin.Cause)) {
235: 					matched = true
236: 					matchedParallel[i] = true
237: 					break
238: 				}
239: 			}
240: 			if matched {
241: 				row.RecallMatched++
242: 			} else {
243: 				row.UnmatchedPairs = append(row.UnmatchedPairs, fmt.Sprintf("builtin-only t%d %s@%s: %s", taskID, repo, head, builtin.Path+" | "+builtin.Cause))
244: 			}
245: 		}
246: 		for i, parallel := range ghFindings {
247: 			if !matchedParallel[i] {
248: 				row.UnmatchedPairs = append(row.UnmatchedPairs, fmt.Sprintf("greenhouse-only t%d %s@%s: %s | %s", taskID, repo, head, parallel.File, parallel.Explanation))
249: 			}
250: 		}
251: 	}
252: 	if err := greenhouse.Err(); err != nil {
253: 		greenhouse.Close()
254: 		return row, nil, err
255: 	}
256: 	greenhouse.Close()
257: 	if row.RecallPairs > 0 {
258: 		recall := float64(row.RecallMatched) / float64(row.RecallPairs)
259: 		row.Recall = &recall
260: 		pass := recall >= 0.90
261: 		row.RecallPass = &pass
262: 	}
263: 	sort.Strings(row.UnmatchedPairs)
264: 	return row, latencies, nil
265: }
