31: func TestReviewParallelIsFrozenWithValidationLoops(t *testing.T) {
32: 	r := request("change")
33: 	r.ValidationLoops = &taskplan.ValidationLoops{Review: config.ReviewLoop{Enabled: true, MaxRounds: 3, BlockAt: "P1", AutoStart: true}, ReviewParallel: "greenhouse"}
34: 	plan, err := taskplan.Resolve(r)
35: 	if err != nil {
36: 		t.Fatal(err)
37: 	}
38: 	r.ValidationLoops.ReviewParallel = ""
39: 	encoded, err := plan.Encode()
40: 	if err != nil {
41: 		t.Fatal(err)
42: 	}
43: 	decoded, err := taskplan.Decode(encoded)
44: 	if err != nil || decoded.ValidationLoops == nil || decoded.ValidationLoops.ReviewParallel != "greenhouse" {
45: 		t.Fatalf("parallel review setting was not frozen: %#v, %v", decoded.ValidationLoops, err)
46: 	}
47: }
